<?php $pageTitle='Attendance';$subtitle='Review GPS attendance, approve or reject records, and mark attendance manually.';$active='Attendance';require __DIR__.'/_layout.php';$pdo=db();$emps=$pdo->query("SELECT id,name FROM users WHERE role='employee' ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT a.*,u.name employee_name FROM attendance a JOIN users u ON u.id=a.employee_id ORDER BY a.attendance_date DESC,a.marked_at DESC LIMIT 200")->fetchAll();$office=$pdo->query('SELECT * FROM office_settings WHERE id=1')->fetch();
$monthStart=date('Y-m-01'); $today=date('Y-m-d'); $daysElapsed=(int)date('j');
$summaryStmt=$pdo->prepare("SELECT u.id,u.name,COUNT(a.id) records,SUM(CASE WHEN a.status='present' THEN 1 ELSE 0 END) present,SUM(CASE WHEN a.status='rejected' THEN 1 ELSE 0 END) rejected,SUM(CASE WHEN a.status='pending' THEN 1 ELSE 0 END) pending FROM users u LEFT JOIN attendance a ON a.employee_id=u.id AND a.attendance_date BETWEEN ? AND ? WHERE u.role='employee' GROUP BY u.id,u.name ORDER BY u.name");
$summaryStmt->execute([$monthStart,$today]); $attendanceSummary=$summaryStmt->fetchAll();
?><section class="card attendance-summary-card" style="margin-bottom:18px">
<div class="section-head"><div><h2>Employee attendance overview</h2><p class="muted">Month-to-date · <?=date('F Y')?> · Percentage = present days ÷ <?= $daysElapsed ?> elapsed calendar days</p></div><span class="pill blue"><?=count($attendanceSummary)?> employees</span></div>
<div class="attendance-summary-grid">
<?php foreach($attendanceSummary as $sr): $present=(int)$sr['present']; $pct=$daysElapsed>0?min(100,round($present/$daysElapsed*100,1)):0; $ring=min(100,$pct); ?>
<div class="attendance-person">
<div class="attendance-ring" style="--progress:<?=$ring?>%"><div><strong><?=$pct?>%</strong><small>present</small></div></div>
<div class="attendance-person-info"><strong><?=ae($sr['name'])?></strong><div class="mini-stats"><span>Present <?=$present?></span><span>Rejected <?=((int)$sr['rejected'])?></span><span>Pending <?=((int)$sr['pending'])?></span></div><small><?=$sr['records']?> recorded days</small></div>
</div>
<?php endforeach; if(!$attendanceSummary):?><div class="empty">No employees found.</div><?php endif;?>
</div></section>
<div class="grid two"><section class="card"><div class="section-head"><h2>Office geofence</h2></div><p style="color:var(--muted);line-height:1.6">Employee attendance is accepted only when the device location is within the configured radius. Browser GPS supplies latitude, longitude, accuracy and altitude when available.</p><form id="officeForm"><div class="form-grid"><div class="field full"><label>Office Name</label><input class="input" name="office_name" value="<?=ae($office['office_name'])?>"></div><div class="field"><label>Latitude</label><input class="input" name="latitude" value="<?=ae($office['latitude'])?>" placeholder="22.5726"></div><div class="field"><label>Longitude</label><input class="input" name="longitude" value="<?=ae($office['longitude'])?>" placeholder="88.3639"></div><div class="field"><label>Radius (meters)</label><input class="input" name="radius_meters" type="number" min="10" max="1000" value="<?=ae($office['radius_meters'])?>"></div></div><button class="btn primary" style="margin-top:15px">Save Location</button></form></section><section class="card"><div class="section-head"><h2>Manual attendance</h2></div><form id="manualForm"><div class="field"><label>Employee</label><select class="select" name="employee_id" required><option value="">Select employee</option><?php foreach($emps as $e):?><option value="<?=$e['id']?>"><?=ae($e['name'])?></option><?php endforeach;?></select></div><div class="field" style="margin-top:12px"><label>Date</label><input class="input" name="attendance_date" type="date" value="<?=date('Y-m-d')?>"></div><div class="field" style="margin-top:12px"><label>Note</label><input class="input" name="note" placeholder="Approved by admin"></div><button class="btn primary" style="margin-top:15px">Mark Present</button></form></section></div><div class="card" style="margin-top:18px"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Date / Time</th><th>GPS</th><th>Distance</th><th>Accuracy</th><th>Method</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=ae($r['employee_name'])?></td><td><?=ae($r['attendance_date'])?><br><small><?=ae($r['marked_at'])?></small></td><td><?=ae($r['latitude']??'—')?>, <?=ae($r['longitude']??'—')?><br><small>Altitude <?=ae($r['altitude']??'—')?> m</small></td><td><?=number_format((float)($r['distance_meters']??0),1)?> m</td><td><?=number_format((float)($r['accuracy']??0),1)?> m</td><td><?=ae($r['method'])?></td><td><span class="pill <?=($r['status']==='present'?'green':($r['status']==='rejected'?'red':'gold'))?>"><?=ae($r['status'])?></span></td><td><?php if($r['status']==='pending'):?><button class="btn primary" onclick="decision(<?=$r['id']?>,'present')">Accept</button> <button class="btn danger" onclick="decision(<?=$r['id']?>,'rejected')">Reject</button><?php else:?>—<?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8" class="empty">No attendance records yet.</td></tr><?php endif;?></tbody></table></div></div><style>
.muted{color:var(--muted);margin:5px 0 0;font-size:13px}.attendance-summary-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px;margin-top:16px}.attendance-person{display:flex;align-items:center;gap:14px;padding:14px;border:1px solid var(--line);border-radius:18px;background:rgba(255,255,255,.025)}.attendance-ring{width:72px;height:72px;min-width:72px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--gold) var(--progress),rgba(255,255,255,.08) 0);position:relative}.attendance-ring:after{content:'';position:absolute;inset:6px;border-radius:50%;background:var(--card)}.attendance-ring>div{position:relative;z-index:1;text-align:center}.attendance-ring strong{display:block;font-size:16px}.attendance-ring small{display:block;color:var(--muted);font-size:9px}.attendance-person-info{min-width:0}.attendance-person-info>strong{display:block;margin-bottom:7px}.attendance-person-info>small{color:var(--muted);font-size:11px}.mini-stats{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:5px}.mini-stats span{font-size:10px;padding:4px 7px;border-radius:999px;background:rgba(255,255,255,.05);color:var(--muted)}
</style><script>document.querySelector('#officeForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('action','save-office');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok)});document.querySelector('#manualForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('action','attendance-manual');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),500)});async function decision(id,status){const j=await api('attendance-decision',{id,status});toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),400)}</script><?php require __DIR__.'/_foot.php'; ?>
